import { Link } from "react-router-dom";
import React, { useState } from 'react';

import apiService from "../services/apiService";
function Inscription() {
    const [selectedValue, setSelectedValue] = useState('')

    const options = [
    { label: 'X1', value: 'X1' },
    { label: 'X2', value: 'X2' },
    { label: 'X3', value: 'X3' },
    { label: 'X4', value: 'X4' },
    { label: 'X5', value: 'X5' },
    
  ];

  const handleChange = (event) => {
    setSelectedValue(event.target.value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Validation
    if (formData.password !== formData.confirmPassword) {
      setError('Les mots de passe ne correspondent pas');
      return;
    }

    if (formData.password.length < 6) {
      setError('Le mot de passe doit contenir au moins 6 caractères');
      return;
    }

    setLoading(true);

    try {
      const { confirmPassword, ...dataToSend } = formData;
      const response = await apiService.register(dataToSend);
      
      if (response.success) {
        alert('Inscription réussie ! Vous pouvez maintenant vous connecter.');
        navigate('/connexion');
      }
    } catch (err: any) {
      setError(err.message || 'Erreur lors de l\'inscription');
    } finally {
      setLoading(false);
    }
  };

    return(
        
            <div className="main-container">
        <div className="form-container">
            <form>
                <h1>Creer un compte</h1>
                <p>Nom complet</p>
                <input type="text" placeholder="Nom complet" required/>
                <p>Email</p>
                <input type="email" placeholder="Entrer votre email" required/>
                <p>Niveaux</p>
                <label htmlFor="mySelect">Choisissez une option:</label>
      <select id="mySelect" value={selectedValue} onChange={handleChange}>
        <option value="">-- Choisissez une option --</option>
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
                <p>Mot de passe</p>
                <input type="password" placeholder="Entrer votre mot de passe" required />
                <button><Link to="/">Creer un compte</Link></button>
                <span>Vous avez deja un compte ? <Link to="/connexion">Connectez-vous</Link></span>
            </form>
        </div>
        {/*<div className="image-container">
            <svg width="692" height="657" viewBox="0 0 692 657" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
            <rect width="692" height="657" fill="url(#pattern0_77_787)"/>
            <defs>
            <pattern id="pattern0_77_787" patternContentUnits="objectBoundingBox" width="1" height="1">
            <use xlink:href="#image0_77_787" transform="matrix(0.0005 0 0 0.000526636 0 -0.0266362)"/>
            </pattern>
            <image id="image0_77_787" width="2000" height="2000" preserveAspectRatio="none" xlink:href="data:image/png;base64,"/>
            </defs>
            </svg>
        </div>*/}
    </div>
        
    )
}
